681:   private async _checkElementIsStable(node: Node): Promise<'error:notconnected' | boolean> {
682:     const continuePolling = Symbol('continuePolling');
683:     let lastRect: { x: number, y: number, width: number, height: number } | undefined;
684:     let stableRafCounter = 0;
685:     let lastTime = 0;
686: 
687:     const check = () => {
688:       const element = this.retarget(node, 'no-follow-label');
689:       if (!element)
690:         return 'error:notconnected';
691: 
692:       // Drop frames that are shorter than 16ms - WebKit Win bug.
693:       const time = this.utils.builtins.performance.now();
694:       if (this._stableRafCount > 1 && time - lastTime < 15)
695:         return continuePolling;
696:       lastTime = time;
697: 
698:       const clientRect = element.getBoundingClientRect();
699:       const rect = { x: clientRect.top, y: clientRect.left, width: clientRect.width, height: clientRect.height };
700:       if (lastRect) {
701:         const samePosition = rect.x === lastRect.x && rect.y === lastRect.y && rect.width === lastRect.width && rect.height === lastRect.height;
702:         if (!samePosition)
703:           return false;
704:         if (++stableRafCounter >= this._stableRafCount)
705:           return true;
706:       }
707:       lastRect = rect;
708:       return continuePolling;
709:     };
